@Composable
internal fun OnlineActionIcon(kind: String, tint: Color, modifier: Modifier = Modifier) {
    val paths = remember(kind) {
        ActionIconPaths[kind].orEmpty().map { PathParser().parsePathString(it).toPath() }
    }
    Canvas(modifier) {
        val scaleFactor = min(size.width, size.height) / ActionIconViewBox
        val dx = (size.width - ActionIconViewBox * scaleFactor) / 2f
        val dy = (size.height - ActionIconViewBox * scaleFactor) / 2f
        withTransform({ translate(dx, dy) }) {
            scale(scaleFactor, scaleFactor, pivot = Offset.Zero) {
                paths.forEach { path -> drawPath(path, tint) }
            }
        }
    }
}
